facts = {
    "The capital of Gambia is Banjul.": True,
    "The capital of Gambia is Libreville.": False,
    "The capital of Nepal is Pokhara.": False,
    "The capital of Canada is Toronto.": False,
    "The capital of Iran is Tehran.": True,
    "The capital of Afghanistan is Kabul.": True,
    "The capital of Malaysia is Kuala Lumpur.": True,
    "The capital of Turkey is Istanbul.": False,
    "The capital of the Nigeria is Abuja.": True,
}

def evaluate(node):
    if isinstance(node, ast.Expression):
        return evaluate(node.body)
    if isinstance(node, ast.Constant):
        if type(node.value) is bool:
            return node.value
        if type(node.value) is int:
            return Fraction(node.value)
        raise ValueError("Unsupported constant")
    if isinstance(node, ast.UnaryOp):
        value = evaluate(node.operand)
        if isinstance(node.op, ast.Not):
            return not value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return value
    if isinstance(node, ast.BoolOp):
        # Evaluate every operand, not merely a short-circuit prefix.
        values = [evaluate(v) for v in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
    if isinstance(node, ast.BinOp):
        a, b = evaluate(node.left), evaluate(node.right)
        if isinstance(node.op, ast.Add):
            return a + b
        if isinstance(node.op, ast.Sub):
            return a - b
        if isinstance(node.op, ast.Mult):
            return a * b
        if isinstance(node.op, ast.Div):
            return a / b
    if isinstance(node, ast.Compare):
        a = evaluate(node.left)
        results = []
        for op, right in zip(node.ops, node.comparators):
            b = evaluate(right)
            if isinstance(op, ast.Gt):
                results.append(a > b)
            elif isinstance(op, ast.LtE):
                results.append(a <= b)
            else:
                raise ValueError("Unsupported comparison")
            a = b
        return all(results)
    if isinstance(node, ast.Call):
        if (not isinstance(node.func, ast.Name)
                or node.func.id not in ("min", "max")
                or node.keywords):
            raise ValueError("Unsupported call")
        values = [evaluate(arg) for arg in node.args]
        return (min if node.func.id == "min" else max)(values)
    raise ValueError("Unsupported syntax")

def normalize(text):
    for statement, value in facts.items():
        text = text.replace(statement, str(value))
    return (text.replace("is less than or equal to", "<=")
                .replace("is greater than", ">"))

try:
    results = {
        label: evaluate(ast.parse(normalize(text), mode="eval"))
        for label, text in expressions.items()
    }
except (SyntaxError, ValueError, ZeroDivisionError) as error:
    print("UNSUPPORTED:", error)
    print("CHECK UNKNOWN")
else:
    for label, value in results.items():
        print(f"({label}) = {value}")
    true_options = [label for label, value in results.items() if value]
    print("True options:", ", ".join(true_options) or "none")
    if len(true_options) == 1:
        print("Expected answer:", true_options[0])
        print("Submitted answer identifies no option.")
        print("CHECK FAIL")
    else:
        print("The question's claim of exactly one true option is false.")
        print("CHECK FAIL")
